import{_ as t,o,c as a,a2 as l}from"./chunks/framework.B7YvHKtj.js";const h=JSON.parse('{"title":"OpenRouter Cloud Models Setup Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/providers/openrouter.md","filePath":"en/docs/providers/openrouter.md"}'),r={name:"en/docs/providers/openrouter.md"};function n(i,e,d,s,c,u){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="openrouter-cloud-models-setup-guide" tabindex="-1">OpenRouter Cloud Models Setup Guide <a class="header-anchor" href="#openrouter-cloud-models-setup-guide" aria-label="Permalink to &quot;OpenRouter Cloud Models Setup Guide&quot;">​</a></h1><p><strong>OpenRouter</strong> is a unified cloud gateway offering access to 200+ state-of-the-art AI models (DeepSeek V3, Gemini 2.5 Flash, Claude 3.5 Haiku, GPT-4o, and more).</p><p>It is the optimal choice for lightweight laptops without dedicated GPUs, or users seeking studio-quality cinematic translations.</p><hr><h2 id="_1-obtain-an-api-key" tabindex="-1">1. Obtain an API Key <a class="header-anchor" href="#_1-obtain-an-api-key" aria-label="Permalink to &quot;1. Obtain an API Key&quot;">​</a></h2><ol><li>Sign up at <a href="https://openrouter.ai/" target="_blank" rel="noreferrer">OpenRouter.ai</a>.</li><li>Navigate to <a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">Keys</a> and click <strong>Create Key</strong>.</li><li>Copy your newly generated key (<code>sk-or-v1-...</code>).</li><li>(Optional) Add a small credit balance (e.g. $5 is enough to translate dozens of full TV seasons).</li></ol><hr><h2 id="_2-recommended-model-pairings" tabindex="-1">2. Recommended Model Pairings <a class="header-anchor" href="#_2-recommended-model-pairings" aria-label="Permalink to &quot;2. Recommended Model Pairings&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Use Case</th><th style="text-align:left;">Translation Model</th><th style="text-align:left;">Supervisor Model</th><th style="text-align:left;">Highlights</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Best Value (Recommended)</strong></td><td style="text-align:left;"><code>deepseek/deepseek-chat</code></td><td style="text-align:left;"><code>google/gemini-2.0-flash-001</code></td><td style="text-align:left;">Highly idiomatic, ultra-affordable (~$0.005 per episode).</td></tr><tr><td style="text-align:left;"><strong>Ultra-Low Latency</strong></td><td style="text-align:left;"><code>google/gemini-2.0-flash-001</code></td><td style="text-align:left;"><code>google/gemini-2.0-flash-001</code></td><td style="text-align:left;">Sub-second response time with near-instant lookahead.</td></tr><tr><td style="text-align:left;"><strong>Studio Quality</strong></td><td style="text-align:left;"><code>anthropic/claude-3.5-haiku</code></td><td style="text-align:left;"><code>anthropic/claude-3.5-haiku</code></td><td style="text-align:left;">Nuanced dialogue, natural rhetoric, exceptional humor handling.</td></tr></tbody></table><hr><h2 id="_3-configuring-cowatcher" tabindex="-1">3. Configuring CoWatcher <a class="header-anchor" href="#_3-configuring-cowatcher" aria-label="Permalink to &quot;3. Configuring CoWatcher&quot;">​</a></h2><ol><li>Open the CoWatcher popup panel.</li><li>Select <strong>OpenRouter</strong> in the <strong>AI Service Provider</strong> dropdown.</li><li>Paste your API key into the <strong>OpenRouter API Key</strong> input.</li><li>Click <strong>Connect</strong>: <ul><li>CoWatcher validates the key and dynamically fetches the available model catalog.</li><li>The status indicator turns 🟢 <strong>Connected</strong>.</li></ul></li><li>Select your <strong>Translation Model</strong> and <strong>Supervisor Model</strong>, then enjoy your shows!</li></ol>',12)])])}const p=t(r,[["render",n]]);export{h as __pageData,p as default};
